package commerce

import (
	"context"
	"encoding/json"
	"kapi/sync/internal/pro"
	"os"
	"strings"
	"testing"
	"time"
)

// Opt-in fixture export. The issuer is newly generated by service(t), not the
// production signing key. Only public key + signed synthetic responses leave it.
func TestExportAndroidTermInteropVectors(t *testing.T) {
	path := os.Getenv("KAPI_TERM_FIXTURE_FILE")
	if path == "" {
		t.Skip("explicit fixture export only")
	}
	s, pub := service(t, &providerNamedStub{name: "wechat"})
	now := time.Date(2026, 11, 2, 0, 0, 0, 0, time.UTC).Unix()
	s.now = func() time.Time { return time.Unix(now, 0) }
	type vector struct {
		Name      string `json:"name"`
		ID        string `json:"id"`
		Nonce     string `json:"nonce"`
		Response  string `json:"response"`
		Permanent bool   `json:"permanent"`
		Until     int64  `json:"valid_until"`
	}
	rows := []vector{}
	nonce := strings.Repeat("b", 32)
	offers := pro.ProductCatalogue().Pricing.Offers
	capture := func(name string, o OrderView, identity string) {
		t.Helper()
		v, e := s.VerifiedOrder(o.ID, identity, nonce)
		if e != nil {
			t.Fatal(e)
		}
		raw, _ := json.Marshal(v)
		g := s.grantLocked(ownerHash(identity))
		rows = append(rows, vector{name, o.ID, nonce, string(raw), g.Permanent, g.Until})
	}
	buy := func(i int, request string, identity string) OrderView {
		t.Helper()
		o, e := s.Create(context.Background(), identity, request, offers[i].ID, "android", "wechat")
		if e != nil {
			t.Fatal(e)
		}
		return o
	}
	pay := func(o OrderView, trade string) {
		t.Helper()
		if e := s.settle("wechat", Receipt{OrderID: o.ID, TradeID: trade, Currency: "CNY", AmountMinor: o.AmountMinor, State: "PAID"}); e != nil {
			t.Fatal(e)
		}
	}
	month := buy(0, "interop-month-00001", owner)
	capture("created", month, owner)
	pay(month, "interop-month-trade")
	capture("monthly_paid", month, owner)
	now += 5 * 86400
	year := buy(1, "interop-year-000001", owner)
	pay(year, "interop-year-trade")
	capture("yearly_renewed", year, owner)
	if e := s.settle("wechat", Receipt{OrderID: month.ID, TradeID: "interop-month-trade", Currency: "CNY", AmountMinor: 690, State: "REFUND", RefundID: "interop-month-refund", RefundMinor: 690}); e != nil {
		t.Fatal(e)
	}
	capture("first_refunded", month, owner)
	if e := s.settle("wechat", Receipt{OrderID: year.ID, TradeID: "interop-year-trade", Currency: "CNY", AmountMinor: 6900, State: "REFUND", RefundID: "interop-year-refund", RefundMinor: 6900}); e != nil {
		t.Fatal(e)
	}
	capture("all_refunded", year, owner)
	other := strings.Repeat("x", 48)
	life := buy(2, "interop-life-000001", other)
	pay(life, "interop-life-trade")
	capture("lifetime_paid", life, other)
	out, _ := json.MarshalIndent(map[string]any{"synthetic": true, "public_key": pub, "vectors": rows}, "", "  ")
	if e := os.WriteFile(path, append(out, '\n'), 0644); e != nil {
		t.Fatal(e)
	}
}
